`src/lib/storage.ts` — storage helpers
```ts
import { createClient } from './supabase/server'

const BUCKET = process.env.SUPABASE_CUSTOMER_BUCKET ?? 'customer-files'

export async function uploadCustomerFile(path: string, file: File | Blob) {
  const supabase = createClient()
  return supabase.storage.from(BUCKET).upload(path, file, { upsert: false })
}

export async function downloadCustomerFile(path: string) {
  const supabase = createClient()
  return supabase.storage.from(BUCKET).download(path)
}

export async function listCustomerFiles(prefix = '') {
  const supabase = createClient()
  return supabase.storage.from(BUCKET).list(prefix)
}

export async function removeCustomerFile(paths: string[]) {
  const supabase = createClient()
  return supabase.storage.from(BUCKET).remove(paths)
}

export async function signedUrl(path: string, expiresIn = 3600) {
  const supabase = createClient()
  return supabase.storage.from(BUCKET).createSignedUrl(path, expiresIn)
}
```

`supabase/storage.sql` — bucket + RLS policies (run in Supabase SQL editor)
```sql
-- Create a private bucket for customer files.
insert into storage.buckets (id, name, public)
values ('customer-files', 'customer-files', false)
on conflict (id) do nothing;

-- RLS: each authenticated user can only touch files under their own user-id prefix.
create policy "customer read own files"
  on storage.objects for select to authenticated
  using (bucket_id = 'customer-files' and (storage.foldername(name))[1] = auth.uid()::text);

create policy "customer upload own files"
  on storage.objects for insert to authenticated
  with check (bucket_id = 'customer-files' and (storage.foldername(name))[1] = auth.uid()::text);

create policy "customer delete own files"
  on storage.objects for delete to authenticated
  using (bucket_id = 'customer-files' and (storage.foldername(name))[1] = auth.uid()::text);
```

